 68	@Repository
 69	public class ProductRepository {
 70	
 71	    private final JdbcClient jdbc;
 72	
 73	    public ProductRepository(JdbcClient jdbc) {
 74	        this.jdbc = jdbc;
 75	    }
 76	
 77	    public Optional<Product> findBySku(String sku) {
 78	        return jdbc.sql("SELECT * FROM product WHERE sku = :sku")
 79	                .param("sku", sku)
 80	                .query(ProductRepository::map)
 81	                .optional();
 82	    }
 83	
 84	    public Map<String, Product> findBySkus(Collection<String> skus) {
 85	        if (skus.isEmpty()) {
 86	            return Map.of();
 87	        }
 88	        return jdbc.sql("SELECT * FROM product WHERE sku IN (:skus)")
 89	                .param("skus", skus)
 90	                .query(ProductRepository::map)
 91	                .list()
 92	                .stream()
 93	                .collect(Collectors.toMap(Product::sku, Function.identity()));
 94	    }
 95	
 96	    /** Lê o estoque travando as linhas até o fim da transação, sempre na ordem do SKU. */
 97	    public Map<String, Integer> lockStock(Collection<String> skus) {
 98	        return jdbc.sql("SELECT sku, stock FROM product WHERE sku IN (:skus) ORDER BY sku FOR UPDATE")
 99	                .param("skus", skus)
100	                .query((rs, n) -> Map.entry(rs.getString("sku"), rs.getInt("stock")))
101	                .list()
102	                .stream()
103	                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
104	    }
