106	    public void changeStock(String sku, int delta) {
107	        jdbc.sql("UPDATE product SET stock = stock + :delta WHERE sku = :sku")
108	                .param("delta", delta)
109	                .param("sku", sku)
110	                .update();
111	    }
112	
113	
114	    /** Peso com pelo menos 2 casas (0.30), sem perder gramas quebradas. */
115	    private static BigDecimal weight(BigDecimal kg) {
116	        BigDecimal stripped = kg.stripTrailingZeros();
117	        return stripped.scale() < 2 ? stripped.setScale(2) : stripped;
