289	/** O crédito do clube entra no saldo quando o pagamento é confirmado e sai se o pedido pago é cancelado. */
290	@Component
291	public class ClubCreditListener implements OrderLifecycleListener {
292	
293	    private final CustomerRepository customers;
294	
295	    public ClubCreditListener(CustomerRepository customers) {
296	        this.customers = customers;
297	    }
298	
299	    @Override
300	    public void paymentApproved(Order order) {
301	        customers.addCredit(order.cpf(), order.summary().nextPurchaseCredit());
302	    }
303	
304	    @Override
305	    public void cancelled(Order order, OrderStatus previousStatus) {
306	        if (previousStatus.paymentSettled()) {
307	            customers.addCredit(order.cpf(), order.summary().nextPurchaseCredit().negate());
308	        }
309	    }
310	}

